/**
 * Unit tests for JacksonAnnotationIntrospector#findRootName
 */
public class JacksonAnnotationIntrospector_findRootName_TriageGen2Test {

    private JacksonAnnotationIntrospector introspector;
    private AnnotatedClass mockAnnotatedClass;

    @Before
    public void setUp() {
        // We spy on the introspector to mock the protected _findAnnotation method
        introspector = Mockito.spy(new JacksonAnnotationIntrospector());
        mockAnnotatedClass = Mockito.mock(AnnotatedClass.class);
    }

    @Test
    public void testFindRootName_NoAnnotationReturnsNull() {
        // Arrange: _findAnnotation returns null
        when(introspector._findAnnotation(mockAnnotatedClass, JsonRootName.class)).thenReturn(null);

        // Act
        PropertyName result = introspector.findRootName(mockAnnotatedClass);

        // Assert
        assertNull("Should return null when no annotation is present", result);
    }

    @Test
    public void testFindRootName_WithAnnotationAndNamespace() {
        // Arrange: Annotation with value and non-empty namespace
        JsonRootName mockAnn = Mockito.mock(JsonRootName.class);
        when(mockAnn.value()).thenReturn("root");
        when(mockAnn.namespace()).thenReturn("http://example.com");
        when(introspector._findAnnotation(mockAnnotatedClass, JsonRootName.class)).thenReturn(mockAnn);

        // Act
        PropertyName result = introspector.findRootName(mockAnnotatedClass);

        // Assert
        assertEquals("PropertyName should match value and namespace", 
            PropertyName.construct("root", "http://example.com"), result);
    }

    @Test
    public void testFindRootName_WithAnnotationAndNullNamespace() {
        // Arrange: Annotation with value and null namespace
        JsonRootName mockAnn = Mockito.mock(JsonRootName.class);
        when(mockAnn.value()).thenReturn("root");
        when(mockAnn.namespace()).thenReturn(null);
        when(introspector._findAnnotation(mockAnnotatedClass, JsonRootName.class)).thenReturn(mockAnn);

        // Act
        PropertyName result = introspector.findRootName(mockAnnotatedClass);

        // Assert
        assertEquals("PropertyName should have null namespace", 
            PropertyName.construct("root", null), result);
    }

    @Test
    public void testFindRootName_WithAnnotationAndEmptyNamespace() {
        // Arrange: Annotation with value and empty string namespace
        // The code contains logic: if (ns != null && ns.length() == 0) { ns = null; }
        JsonRootName mockAnn = Mockito.mock(JsonRootName.class);
        when(mockAnn.value()).thenReturn("root");
        when(mockAnn.namespace()).thenReturn("");
        when(introspector._findAnnotation(mockAnnotatedClass, JsonRootName.class)).thenReturn(mockAnn);

        // Act
        PropertyName result = introspector.findRootName(mockAnnotatedClass);

        // Assert
        assertEquals("Empty namespace should be treated as null", 
            PropertyName.construct("root", null), result);
    }
}
